using System;using System.Linq;using System.Reflection;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using Racer;using Object=UnityEngine.Object;
public static class ClearDrainTrees{public static string Main(){var b=Object.FindObjectsByType<WoodlandRoute>().Single(x=>x.title.StartsWith("Storm"));int count=0;bool Cut(Collider c){float s=b.Project(c.bounds.center,out float side);bool cut=s>10&&s<100&&side<5&&c.bounds.min.y<b.At(s,out _).y+6.4f&&c.bounds.max.y>b.At(s,out _).y;if(cut)count++;return cut;}typeof(Racer.Editor.BackyardReverseAuthoring).GetMethod("Trees",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{(Func<Collider,bool>)Cut,(Func<Collider,bool>)(c=>false)});EditorSceneManager.MarkSceneDirty(b.gameObject.scene);EditorSceneManager.SaveScene(b.gameObject.scene);AssetDatabase.SaveAssets();File.WriteAllText("Docs/SevenCorrections/drain-tree-clearance.txt",$"Removed {count} complete trees (trunk collider and connected combined crown/trunk meshes) intersecting bore/portal; no floating tree remnants retained.");return count+" full trees removed from bore";}}
